package main

import "testing"

// The oracle must read a mutant the way both verifiers read it: fields by
// name, an absent field as null, an unknown field not at all, a payload
// whole. Every case here is a mutant kind the differential has produced.
func TestSemanticallySame(t *testing.T) {
	event := `{"action":"user.login","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":35,"v":1}`
	checkpoints := `{"checkpoints":[{"v":1,"stream":"019b","from":1,"to":10,"root":"4724aed3af896157efa69da5ecca3c6b41993ece4d77f4c855d38185396c50fc","prev_checkpoint":"00","created_at":"2026-01-02T03:04:05.000000Z"}]}`

	cases := []struct {
		name   string
		file   string
		before string
		after  string
		same   bool
	}{
		{"null field removed", "events.ndjson", event, `{"action":"user.login","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","seq":35,"v":1}`, true},
		{"null field renamed", "events.ndjson", event, `{"action":"user.login","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resourc%":null,"seq":35,"v":1}`, true},
		{"unverified field renamed", "events.ndjson", event, `{"action":"user.login","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"n":35},"payload_hash":"046F","pa{load_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":35,"v":1}`, true},
		{"unknown field added", "events.ndjson", event, `{"action":"user.login","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","note":"x","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":35,"v":1}`, true},
		{"hash case changed", "events.ndjson", event, `{"action":"user.login","actor":"user:1","entry_hash":"2EF2182B89B816CFAA6504DACD62B8A5237719F81BA9DCC9F77A238A48A7C139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":35,"v":1}`, true},
		{"whitespace only", "events.ndjson", event, `{"action": "user.login", "actor": "user:1", "entry_hash": "2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139", "occurred_at": "2026-01-02T03:04:05.000000Z", "payload": {"a": null, "n": 35}, "payload_hash": "046F", "payload_state": "present", "prev_hash": "4427", "received_at": "2026-01-02T03:04:05.000000Z", "resource": null, "seq": 35, "v": 1}`, true},
		{"hashed field removed", "events.ndjson", event, `{"action":"user.login","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":35,"v":1}`, false},
		{"hashed field renamed", "events.ndjson", event, `{"action":"user.login","acto%":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":35,"v":1}`, false},
		{"null field given a value", "events.ndjson", event, `{"action":"user.login","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":"doc:1","seq":35,"v":1}`, false},
		{"null inside payload removed", "events.ndjson", event, `{"action":"user.login","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":35,"v":1}`, false},
		{"field inside payload added", "events.ndjson", event, `{"action":"user.login","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"b":1,"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":35,"v":1}`, false},
		{"line removed", "events.ndjson", event + "\n" + event, event, false},
		{"line no longer parses", "events.ndjson", event, event[:len(event)-1], false},
		{"checkpoint unverified fields renamed", "checkpoints.json", checkpoints, `{"checkpoints":[{"r":1,"stpeam":"019b","from":1,"to":10,"root":"4724aed3af896157efa69da5ecca3c6b41993ece4d77f4c855d38185396c50fc","prev_checkpoint":"00","created_at":"2026-01-02T03:04:05.000000Z"}]}`, true},
		{"checkpoint root case changed", "checkpoints.json", checkpoints, `{"checkpoints":[{"v":1,"stream":"019b","from":1,"to":10,"root":"4724AED3AF896157EFA69DA5ECCA3C6B41993ECE4D77F4C855D38185396C50FC","prev_checkpoint":"00","created_at":"2026-01-02T03:04:05.000000Z"}]}`, true},
		{"checkpoint root changed", "checkpoints.json", checkpoints, `{"checkpoints":[{"v":1,"stream":"019b","from":1,"to":10,"root":"5724aed3af896157efa69da5ecca3c6b41993ece4d77f4c855d38185396c50fc","prev_checkpoint":"00","created_at":"2026-01-02T03:04:05.000000Z"}]}`, false},
		{"checkpoint removed", "checkpoints.json", checkpoints, `{"checkpoints":[]}`, false},
		{"unknown field removed from an event", "events.ndjson", `{"action":"user.login","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","note":"x","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"a":null,"n":35},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":35,"v":1}`, event, true},
		{"unknown field removed from a checkpoint", "checkpoints.json", `{"checkpoints":[{"v":1,"stream":"019b","from":1,"to":10,"root":"4724aed3af896157efa69da5ecca3c6b41993ece4d77f4c855d38185396c50fc","prev_checkpoint":"00","created_at":"2026-01-02T03:04:05.000000Z","note":"x"}]}`, checkpoints, true},
		{"checkpoint public key changed", "checkpoints.json", `{"checkpoints":[{"v":1,"from":1,"to":10,"root":"4724aed3af896157efa69da5ecca3c6b41993ece4d77f4c855d38185396c50fc","prev_checkpoint":"00","created_at":"2026-01-02T03:04:05.000000Z","public_key":"d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a"}]}`, `{"checkpoints":[{"v":1,"from":1,"to":10,"root":"4724aed3af896157efa69da5ecca3c6b41993ece4d77f4c855d38185396c50fc","prev_checkpoint":"00","created_at":"2026-01-02T03:04:05.000000Z","public_key":"e75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a"}]}`, false},
		{"declaration slug removed", "declarations.ndjson", `{"action":"payload.redacted","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"count":1},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":41,"stream":"019b","stream_slug":"conformance","v":1}`, `{"action":"payload.redacted","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"count":1},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":41,"stream":"019b","v":1}`, true},
		{"declaration stream removed", "declarations.ndjson", `{"action":"payload.redacted","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"count":1},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":41,"stream":"019b","stream_slug":"conformance","v":1}`, `{"action":"payload.redacted","actor":"user:1","entry_hash":"2ef2182b89b816cfaa6504dacd62b8a5237719f81ba9dcc9f77a238a48a7c139","occurred_at":"2026-01-02T03:04:05.000000Z","payload":{"count":1},"payload_hash":"046F","payload_state":"present","prev_hash":"4427","received_at":"2026-01-02T03:04:05.000000Z","resource":null,"seq":41,"stream_slug":"conformance","v":1}`, false},
		{"checkpoint hashed field renamed", "checkpoints.json", checkpoints, `{"checkpoints":[{"v":1,"stream":"019b","from":1,"to":10,"roo%":"4724aed3af896157efa69da5ecca3c6b41993ece4d77f4c855d38185396c50fc","prev_checkpoint":"00","created_at":"2026-01-02T03:04:05.000000Z"}]}`, false},
	}
	for _, c := range cases {
		if got := semanticallySame(c.file, []byte(c.before), []byte(c.after)); got != c.same {
			t.Errorf("%s: semanticallySame = %v, want %v", c.name, got, c.same)
		}
	}
}
